package com.jnapanam.sportszone.notification.provider;
import com.jnapanam.sportszone.notification.model.*;import java.util.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.http.*;import org.springframework.stereotype.Component;import org.springframework.web.client.RestClient;
@Component public class Fast2SmsNotificationProvider implements SmsNotificationProvider{private final RestClient http=RestClient.create();private final String url,key,senderId,route;public Fast2SmsNotificationProvider(@Value("${app.notification.sms.fast2sms.url:https://www.fast2sms.com/dev/bulkV2}")String url,@Value("${app.notification.sms.fast2sms.api-key:}")String key,@Value("${app.notification.sms.fast2sms.sender-id:}")String senderId,@Value("${app.notification.sms.fast2sms.route:q}")String route){this.url=url;this.key=key;this.senderId=senderId;this.route=route;}public NotificationChannel channel(){return NotificationChannel.SMS;}public String name(){return "fast2sms";}public String send(Notification n){if(key==null||key.isBlank())throw new IllegalStateException("FAST2SMS_API_KEY is not configured");String mobile=n.getUser().getMobile();if(mobile==null||mobile.isBlank())throw new IllegalStateException("User mobile is missing");Map<String,Object> body=new LinkedHashMap<>();body.put("route",route);body.put("message",n.getMessage());body.put("numbers",normalize(mobile));if(senderId!=null&&!senderId.isBlank())body.put("sender_id",senderId);Map response=http.post().uri(url).header("Authorization",key).contentType(MediaType.APPLICATION_JSON).body(body).retrieve().body(Map.class);if(response!=null&&Boolean.FALSE.equals(response.get("return")))throw new IllegalStateException(String.valueOf(response.getOrDefault("message","Fast2SMS rejected request")));Object id=response==null?null:response.get("request_id");return id==null?"fast2sms-"+n.getId():id.toString();}private String normalize(String s){String d=s.replaceAll("\\D","");return d.startsWith("91")&&d.length()==12?d.substring(2):d;}}
